-- G9 native800 final SQL gate only. No operator/workflow/source authority issuer.
-- All old RPCs and the import-state check(false) remain byte-identical.
create function private_fcf_native800.launch_stage(t text,h text,d jsonb,ready_sha text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare a jsonb;v jsonb;binding jsonb;n text;begin
 perform private_fcf_six_target_release.require(octet_length(t)between 2 and 65536 and h~'^[a-f0-9]{64}$'and encode(sha256(convert_to(t,'UTF8')),'hex')=h,'exact bounded launch stage TEXT/SHA');a:=t::jsonb;v:=(d#>>'{originalImport,rolloutText}')::jsonb;binding:=v->'inventoryBinding';
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(a,array['schemaVersion','kind','stage','targetSlug','sourceCommit','execution','readinessSha256','rolloutSha256','sourceBindingSha256','counter'])and a->'schemaVersion'='1'::jsonb and a->>'kind'='fcf-native800-launch-stage-attestation'and a->>'stage'='launch'and a->>'targetSlug'='es-ct-tercera-g9'and a->>'readinessSha256'=ready_sha and a->>'rolloutSha256'=d#>>'{originalImport,rolloutSha256}'and a->>'sourceCommit'=v->>'sourceCommit'and a#>>'{execution,commit}'=v->>'sourceCommit'and a->>'sourceBindingSha256'=encode(sha256(convert_to(private_fcf_future_import.canonical_json(binding),'UTF8')),'hex'),'closed launch stage/exact original native writer/current source');
 -- Reuse ONLY the native800 fresh counter/execution validator, not legacy478.
 n:=((a-array['kind','stage','readinessSha256'])||jsonb_build_object('kind','fcf-native800-stage-attestation','stage','check'))::text;perform private_fcf_native800.stage_attestation(n,encode(sha256(convert_to(n,'UTF8')),'hex'),v,'check',d#>>'{originalImport,rolloutSha256}');
 return a;
end$$;
create function private_fcf_native800.launch_readiness(a jsonb,v jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare d jsonb:=(a->>'launchReadinessText')::jsonb;replay jsonb;price jsonb;rec private_fcf_future_target_release.receipts%rowtype;begin
 perform private_fcf_six_target_release.require(octet_length(a->>'launchReadinessText')between 2 and 33554432 and encode(sha256(convert_to(a->>'launchReadinessText','UTF8')),'hex')=a->>'launchReadinessSha256','original exact bounded readiness TEXT/SHA');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(d,array['schemaVersion','kind','protocol','targetSlug','sourceBinding','capture','originalImport','nativeSnapshotText','nativeSnapshotSha256','scoreBeforeimages','pricingSnapshotText','pricingSnapshotSha256','pricingReplayText','pricingReplaySha256','modelSha256','priceVector','cheapestLegal15','legal15PlayerIds','launchProposal','admissible','nativeAdmission','activationEligible'])and d->'schemaVersion'='1'::jsonb and d->>'kind'='fcf-g9-native800-readiness-data'and d->>'protocol'='fcf-g9-native800-v1'and d->>'targetSlug'='es-ct-tercera-g9'and d->'sourceBinding'=v->'inventoryBinding'and d->'capture'=v#>'{inventoryBinding,currentCapture}'and d->'admissible'='false'::jsonb and d->'nativeAdmission'='false'::jsonb and d->'activationEligible'='false'::jsonb,'closed new800 readiness DATA, never admission authority');
 select *into strict rec from private_fcf_future_target_release.receipts where competition_id=797;
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(d->'originalImport',array['stage','receiptId','rolloutText','rolloutSha256','targetPacketSha256','sourceFingerprintSha256','importedStateSha256','currentStateSha256','currentActive'])and d#>>'{originalImport,stage}'='imported'and d#>>'{originalImport,receiptId}'=rec.id::text and d#>>'{originalImport,rolloutText}'=rec.rollout_text and d#>>'{originalImport,rolloutSha256}'=rec.rollout_sha256 and d#>>'{originalImport,targetPacketSha256}'=rec.packet_sha256 and d#>>'{originalImport,sourceFingerprintSha256}'=rec.source_fingerprint and d#>>'{originalImport,importedStateSha256}'=rec.imported_state_sha256 and d#>>'{originalImport,currentStateSha256}'=rec.imported_state_sha256 and d#>'{originalImport,currentActive}'='false'::jsonb,'retained exact original PREPRICE import receipt, not a fresh state assertion');
 perform private_fcf_native800.launch_stage(a->>'launchStageText',a->>'launchStageSha256',d,a->>'launchReadinessSha256');
 perform private_fcf_native800.anchor_before(a,v,rec);perform private_fcf_native800.selected_scores();perform private_fcf_six_target_release.require(v#>'{scoreBeforeimages,offTargetG1}'=private_fcf_native800.score_state(783),'original full off-target G1 preserved after pricing');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(d->'scoreBeforeimages',array['selectedG9','offTargetG1'])and d#>'{scoreBeforeimages,selectedG9}'=private_fcf_native800.score_state(797)and d#>'{scoreBeforeimages,offTargetG1}'=private_fcf_native800.score_state(783)and d#>'{scoreBeforeimages,offTargetG1}'=v#>'{scoreBeforeimages,offTargetG1}','both exact dynamic postprice full score vectors, original G1 preserved');
 perform private_fcf_six_target_release.require(d->>'nativeSnapshotText'=a->>'nativeSnapshotText'and d->>'nativeSnapshotSha256'=a->>'nativeSnapshotSha256'and d->'launchProposal'=a->'launchProposal','same full native snapshot and frozen proposal');
 perform private_fcf_six_target_release.require(d->>'modelSha256'='964854cd20fae2e58d4ba74156ca2be8aa9de0e3c8d69340f0a0a92211118f67'and octet_length(d->>'pricingReplayText')between 2 and 33554432 and encode(sha256(convert_to(d->>'pricingReplayText','UTF8')),'hex')=d->>'pricingReplaySha256','fixed immutable pricing model and exact replay TEXT/SHA');replay:=(d->>'pricingReplayText')::jsonb;price:=(d->>'pricingSnapshotText')::jsonb;
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(replay,array['schemaVersion','kind','targetSlug','competitionId','season','modelSha256','computedCount','threshold','players'])and replay->'schemaVersion'='1'::jsonb and replay->>'kind'='fcf-target-price-replay'and replay->>'targetSlug'='es-ct-tercera-g9'and replay->'competitionId'='797'::jsonb and replay->>'season'='2026/27'and replay->>'modelSha256'=d->>'modelSha256'and jsonb_typeof(replay->'computedCount')='number'and(replay->>'computedCount')~'^[1-9][0-9]*$'and(replay->>'computedCount')::bigint<=jsonb_array_length(price->'players')and jsonb_typeof(replay->'threshold')='number'and(replay->>'threshold')::numeric>=0 and(replay->>'threshold')::numeric::text not in('NaN','Infinity','-Infinity')and jsonb_array_length(replay->'players')=jsonb_array_length(price->'players'),'closed current model/replay scope, finite counters and full vector cardinality');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(replay->'players')x where not private_fcf_future_import.keys(x,array['id','value','value_start','position','position_source']))and not exists(with actual as(select jsonb_build_object('id',id,'value',value,'value_start',value_start,'position',position,'position_source',position_source)j from players where competition_id=797),expected as(select value j from jsonb_array_elements(replay->'players'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual))and(select jsonb_agg(x order by(x->>'id')::bigint)from jsonb_array_elements(replay->'players')x)=(select jsonb_agg(x order by(x->>'id')::bigint)from jsonb_array_elements(d->'priceVector')x),'independent full persisted/replay/readiness price and provenance vectors');
end$$;
create function private_fcf_native800.launch_preserve(d jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare p jsonb;b jsonb:=(d->>'nativeSnapshotText')::jsonb;price jsonb:=(d->>'pricingSnapshotText')::jsonb;current_price jsonb;begin
 p:=private_fcf_native800.capture_current('es-ct-tercera-g9',array(select jsonb_array_elements_text(b#>'{privacy,checkedKeys}')));perform private_fcf_native800.humans(p);perform private_fcf_native800.selected_scores();perform private_fcf_six_target_release.no_target_users(797);
 perform private_fcf_six_target_release.require(d#>'{scoreBeforeimages,selectedG9}'=private_fcf_native800.score_state(797)and d#>'{scoreBeforeimages,offTargetG1}'=private_fcf_native800.score_state(783),'activation preserves both exact score TEXT/SHA vectors');
 perform private_fcf_six_target_release.require(b->'catalog'=(p->>'dependencySnapshotText')::jsonb->'catalog'and b->'shapes'=(p->>'dependencySnapshotText')::jsonb->'shapes'and not exists(select 1 from jsonb_each(b->'relations')r where r.key not in('public.competitions','public.rounds','private_historical_statistics.installed_policies','private_historical_statistics.release_authorizations','private_fcf_future_target_release.receipts')and r.value is distinct from((p->>'dependencySnapshotText')::jsonb)#>array['relations',r.key]),'all non-owned protected relation hashes/catalog/shapes byte-identical through activation');
 perform private_fcf_six_target_release.require(private_fcf_native800.off_target_priors()=(select case when stage='imported'then activation_result->'offTargetPriors'else((activation_result->>'activationText')::jsonb)#>'{priceBefore,offTargetPriors}'end from private_fcf_future_target_release.receipts where competition_id=797),'whole raw off-target prior server anchor preserved through activation');
 current_price:=(p#>>'{pricingSnapshot,snapshotText}')::jsonb;
 perform private_fcf_six_target_release.require(price-array['stateSha256','priorCompetitions']=current_price-array['stateSha256','priorCompetitions']and(select jsonb_agg(x order by(x->>'id')::bigint)from jsonb_array_elements(price->'priorCompetitions')x where x->>'id'<>'797')=(select jsonb_agg(x order by(x->>'id')::bigint)from jsonb_array_elements(current_price->'priorCompetitions')x where x->>'id'<>'797'),'full pricing inputs/provenance and every off-target competition preserved');
end$$;
create function private_fcf_native800.launch_after_image(cid bigint)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare p jsonb;s jsonb;begin
 perform private_fcf_six_target_release.require(cid=797,'fixed new800 G9 afterimage');p:=private_fcf_native800.capture_current('es-ct-tercera-g9',array[]::text[]);perform private_fcf_native800.humans(p);perform private_fcf_native800.selected_scores();perform private_fcf_native800.anchor_definition_guard();s:=(p->>'dependencySnapshotText')::jsonb;
 -- Exclude only the self-containing receipt row hash. Payload/stage is closed
 -- separately and exact original readiness TEXT/SHA is durably stored there.
 s:=jsonb_set(s,'{relations}',(s->'relations')-'private_fcf_future_target_release.receipts');return jsonb_build_object('snapshot',s,'selectedG9',private_fcf_native800.score_state(797),'offTargetG1',private_fcf_native800.score_state(783),'offTargetPriors',private_fcf_native800.off_target_priors());
end$$;



