create function private_fcf_native800.launch_fresh(a jsonb,v jsonb)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_native800.source_binding(v->'inventoryBinding',((v->>'targetPacketText')::jsonb)#>'{target,fixtures}');
 perform private_fcf_native800.launch_stage(a->>'launchStageText',a->>'launchStageSha256',(a->>'launchReadinessText')::jsonb,a->>'launchReadinessSha256');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(((v->>'targetPacketText')::jsonb)#>'{target,fixtures}')f where f->>'statisticsStatus'='pending'and clock_timestamp()-((f->>'date')::date::timestamp at time zone'UTC')between interval'-1 day'and interval'14 days'and(f#>>'{source,capturedUTC}')::timestamptz<clock_timestamp()-interval'1 hour'),'original pending-provider1h freshness at final launch boundary; no renewal');
end$$;
create function public.fcf_native800_launch_receipt(p_slug text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare rec private_fcf_future_target_release.receipts%rowtype;a jsonb;d jsonb;after_image jsonb;after_text text;begin
 perform private_fcf_six_target_release.require(p_slug='es-ct-tercera-g9'and current_setting('transaction_read_only')='on','explicit READ ONLY fixed native800 launch recovery');
 perform private_fcf_six_target_release.require((select count(*)from private_fcf_future_target_release.receipts where competition_id=797)<=1,'single native800 launch receipt only');select *into rec from private_fcf_future_target_release.receipts where competition_id=797;if rec.id is null or rec.stage='imported'then return null;end if;
 a:=(rec.activation_result->>'activationText')::jsonb;d:=(a->>'launchReadinessText')::jsonb;after_image:=private_fcf_native800.launch_after_image(797);after_text:=after_image::text;
 perform private_fcf_six_target_release.require(rec.stage='activated'and(select active from competitions where id=797)and a->>'kind'='fcf-native800-launch-envelope'and a->>'importRolloutText'=rec.rollout_text and a->>'importRolloutSha256'=rec.rollout_sha256 and rec.rollout_sha256=encode(sha256(convert_to(rec.rollout_text,'UTF8')),'hex')and rec.activation_result->>'activationSha256'=encode(sha256(convert_to(rec.activation_result->>'activationText','UTF8')),'hex')and a->>'launchReadinessSha256'=encode(sha256(convert_to(a->>'launchReadinessText','UTF8')),'hex')and rec.activation_result->'afterImage'=after_image and d#>'{scoreBeforeimages,offTargetG1}'=private_fcf_native800.score_state(783),'exact saved launch payload/current complete afterimage and dynamic G1 preservation; any drift remains HOLD');
 return jsonb_build_object('schemaVersion',1,'kind','fcf-native800-launch-receipt','targetSlug','es-ct-tercera-g9','receiptId',rec.id::text,'stage','activated','readinessSha256',a->>'launchReadinessSha256','rolloutSha256',rec.rollout_sha256,'targetPacketSha256',rec.packet_sha256,'sourceFingerprintSha256',rec.source_fingerprint,'execution',a->'execution','afterImageText',after_text,'afterImageSha256',encode(sha256(convert_to(after_text,'UTF8')),'hex'),'result',rec.activation_result->'result','currentActive',true,'admissible',false,'nativeAdmission',false,'activationEligible',false);
end$$;
create function public.fcf_native800_launch(p_readiness_text text,p_sha256 text,p_activate boolean,p_stage_text text,p_stage_sha256 text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare d jsonb;stage jsonb;a jsonb;t text;rec private_fcf_future_target_release.receipts%rowtype;v jsonb;r jsonb;begin
 perform set_config('lock_timeout','10s',true);perform private_fcf_six_target_release.require(p_activate is not null and octet_length(p_readiness_text)between 2 and 33554432 and p_sha256~'^[a-f0-9]{64}$'and encode(sha256(convert_to(p_readiness_text,'UTF8')),'hex')=p_sha256,'exact bounded final readiness TEXT/SHA and explicit activation boolean');
 perform private_fcf_six_target_release.lock_target(797);perform private_fcf_future_import.lock_dependencies();d:=p_readiness_text::jsonb;stage:=private_fcf_native800.launch_stage(p_stage_text,p_stage_sha256,d,p_sha256);
 select *into strict rec from private_fcf_future_target_release.receipts where competition_id=797;
 perform private_fcf_six_target_release.require(d#>>'{originalImport,rolloutText}'=rec.rollout_text and d#>>'{originalImport,rolloutSha256}'=rec.rollout_sha256,'original launch import receipt payload');v:=rec.rollout_text::jsonb;
 a:=jsonb_build_object('schemaVersion',1,'kind','fcf-native800-launch-envelope','targetSlug','es-ct-tercera-g9','sourceCommit',v->>'sourceCommit','execution',stage->'execution','importReceiptId',rec.id::text,'importRolloutText',rec.rollout_text,'importRolloutSha256',rec.rollout_sha256,'nativeSnapshotText',d->>'nativeSnapshotText','nativeSnapshotSha256',d->>'nativeSnapshotSha256','launchProposal',d->'launchProposal','auditedUTC',stage#>>'{counter,verifiedUTC}','launchReadinessText',p_readiness_text,'launchReadinessSha256',p_sha256,'launchStageText',p_stage_text,'launchStageSha256',p_stage_sha256,'priceBefore',rec.activation_result,'readiness',jsonb_build_object('modelSha256',d->>'modelSha256','pricingSnapshotText',d->>'pricingSnapshotText','pricingSnapshotSha256',d->>'pricingSnapshotSha256','priceVector',d->'priceVector','squad',(select jsonb_agg(jsonb_build_object('id',x)order by x::bigint)from jsonb_array_elements(d->'legal15PlayerIds')x),'cheapestLegal15',d->'cheapestLegal15','launchProposal',d->'launchProposal'));
 perform private_fcf_native800.launch_fresh(a,v);
 if rec.stage='activated'then
  -- Exact-payload retry is readback only; a new counter timestamp is not a new
  -- write permit. Preserve the original saved launch execution as well.
  perform private_fcf_six_target_release.require(rec.activation_result#>>'{activationText}'is not null and((rec.activation_result->>'activationText')::jsonb)->>'launchReadinessText'=p_readiness_text and((rec.activation_result->>'activationText')::jsonb)->>'launchReadinessSha256'=p_sha256 and((rec.activation_result->>'activationText')::jsonb)->'execution'=stage->'execution'and rec.activation_result->'afterImage'=private_fcf_native800.launch_after_image(797),'exact committed readiness/execution/current afterimage only; no blind retry');
  return rec.activation_result->'result'||jsonb_build_object('schemaVersion',1,'kind','fcf-native800-launch-result','readinessSha256',p_sha256,'noOp',true,'readbackOnly',true,'admissible',false,'nativeAdmission',false,'activationEligible',false);
 end if;
 t:=a::text;r:=private_fcf_native800.launch_transaction(t,encode(sha256(convert_to(t,'UTF8')),'hex'),p_activate);
 perform private_fcf_native800.launch_fresh(a,v);return r||jsonb_build_object('schemaVersion',1,'kind','fcf-native800-launch-result','readinessSha256',p_sha256,'admissible',false,'nativeAdmission',false,'activationEligible',false);
end$$;
revoke all on all functions in schema private_fcf_native800 from public,anon,authenticated,service_role;
revoke all on function public.fcf_native800_launch(text,text,boolean,text,text),public.fcf_native800_launch_receipt(text)from public,anon,authenticated;
grant execute on function public.fcf_native800_launch(text,text,boolean,text,text),public.fcf_native800_launch_receipt(text)to service_role;
-- Atomic original server anchor, before ANY later price-child request. Orphan
-- priors are OFFTARGET: NOT EXISTS never drops rows with missing/null players.
create function private_fcf_native800.off_target_priors()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$with actual as(select coalesce(jsonb_agg(to_jsonb(x)order by to_jsonb(x)::text collate "C"),'[]'::jsonb)rows from position_priors x where not exists(select 1 from players p where p.id=x.player_id and p.competition_id=797))select jsonb_build_object('count',jsonb_array_length(rows),'snapshotText',rows::text,'snapshotSha256',encode(sha256(convert_to(rows::text,'UTF8')),'hex'))from actual$$;
create function private_fcf_native800.price_anchor()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare v jsonb;begin
 begin v:=new.rollout_text::jsonb;exception when invalid_text_representation then return new;end;
 if v->>'kind'is distinct from'fcf-native800-import-rollout'and v->>'protocol'is distinct from'fcf-native800-v1' then return new;end if;
 perform private_fcf_native800.anchor_definition_guard();
 perform private_fcf_six_target_release.require(new.competition_id=797 and new.stage='imported'and new.activation_result is null and v->>'kind'='fcf-native800-import-rollout'and v->>'protocol'='fcf-native800-v1'and new.rollout_sha256=encode(sha256(convert_to(new.rollout_text,'UTF8')),'hex'),'fixed G9 native800 imported NULL-metadata server anchor only');
 new.activation_result:=jsonb_build_object('schemaVersion',1,'kind','fcf-native800-price-before','rolloutSha256',new.rollout_sha256,'sourceFingerprintSha256',new.source_fingerprint,'sourceBindingSha256',encode(sha256(convert_to(private_fcf_future_import.canonical_json(v->'inventoryBinding'),'UTF8')),'hex'),'capture',v#>'{inventoryBinding,currentCapture}','targetPlayerIds',(select coalesce(jsonb_agg(id order by id),'[]')from players where competition_id=797),'offTargetPriors',private_fcf_native800.off_target_priors());
 perform private_fcf_six_target_release.require(octet_length(new.activation_result#>>'{offTargetPriors,snapshotText}')<=33554432,'bounded complete off-target prior anchor; never truncate');return new;
end$$;
create trigger fcf_native800_price_anchor before insert on private_fcf_future_target_release.receipts for each row execute function private_fcf_native800.price_anchor();
create function private_fcf_native800.anchor_before(a jsonb,v jsonb,rec private_fcf_future_target_release.receipts)returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare b jsonb:=rec.activation_result;prior jsonb;begin
 perform private_fcf_native800.anchor_definition_guard();
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(b,array['schemaVersion','kind','rolloutSha256','sourceFingerprintSha256','sourceBindingSha256','capture','targetPlayerIds','offTargetPriors'])and b->'schemaVersion'='1'::jsonb and b->>'kind'='fcf-native800-price-before'and b->>'rolloutSha256'=rec.rollout_sha256 and b->>'sourceFingerprintSha256'=rec.source_fingerprint and b->>'sourceBindingSha256'=encode(sha256(convert_to(private_fcf_future_import.canonical_json(v->'inventoryBinding'),'UTF8')),'hex')and b->'capture'=v#>'{inventoryBinding,currentCapture}'and b->'targetPlayerIds'=(select coalesce(jsonb_agg(id order by id),'[]')from players where competition_id=797)and b->'offTargetPriors'=private_fcf_native800.off_target_priors()and a->'priceBefore'=b,'exact server-anchored original nonG9 priors/scope/source epoch before pricing; caller hash is insufficient');
 prior:=(v->>'nativeSnapshotText')::jsonb;
 -- position_priors is the one additional OWNED stock position-child relation;
 -- its nonG9 raw rows are independently server-anchored above. Every target
 -- row is then frozen in the full postprice snapshot through final activation.
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_each(prior->'relations')r where r.key not in('public.players','public.matches','public.rounds','public.appearances','public.goals','public.player_scores','public.statistika_igralcev','public.position_priors','private_fcf_six_target_release.club_bindings','private_fcf_future_target_release.receipts')and r.value is distinct from(((a->>'nativeSnapshotText')::jsonb)#>array['relations',r.key])),'original import non-owned relations unchanged through stock price-child stage');
end$$;
revoke all on all functions in schema private_fcf_native800 from public,anon,authenticated,service_role;

create function private_fcf_native800.anchor_definition_guard()returns void language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform private_fcf_six_target_release.require((select count(*)from pg_trigger where tgrelid='private_fcf_future_target_release.receipts'::regclass and not tgisinternal)=1 and exists(select 1 from pg_trigger where tgrelid='private_fcf_future_target_release.receipts'::regclass and not tgisinternal and tgname='fcf_native800_price_anchor'and tgtype=7 and tgenabled='O'and tgfoid='private_fcf_native800.price_anchor()'::regprocedure and tgconstraint=0 and tgqual is null and tgnargs=0 and octet_length(tgargs)=0 and tgoldtable is null and tgnewtable is null),'exact sole reviewed receipt BEFORE INSERT trigger; unknown trigger stays HOLD');
 perform private_fcf_six_target_release.require((select encode(sha256(convert_to(prosrc,'UTF8')),'hex')='86c829b510036f7fd67da91065e76c7d9f4a7abbd288f57256e5b6395ea17f87'and prosecdef from pg_proc where oid='private_fcf_native800.off_target_priors()'::regprocedure),'exact immutable off_target_priors definition');
 perform private_fcf_six_target_release.require((select encode(sha256(convert_to(prosrc,'UTF8')),'hex')='878542eefa6a9356566f1701bea442202b2a266a94fd4e07eb477b0255a0917c'and prosecdef from pg_proc where oid='private_fcf_native800.price_anchor()'::regprocedure),'exact immutable price_anchor definition');
end$$;
revoke all on all functions in schema private_fcf_native800 from public,anon,authenticated,service_role;
select private_fcf_native800.anchor_definition_guard();
